import { useId, type JSX } from "react";

/**
 * Full-colour provider marks, drawn beside a model id (Figma
 * `card/choose-model` 665:18400 at 16px; the PAYG confirmation's `130:48325`
 * at 20px).
 *
 * **Colour, not `currentColor`** - which is why this is not more `BrandMark`
 * entries. That file is the monochrome counterpart for the rail's dark app
 * tiles, whose own `logo` set (Figma 408:14159) exports every variant at
 * `#F9FAFB` precisely so the tile can ink it. These sit on a white row and
 * carry their own brand colour. The two files overlap on anthropic and openai
 * on purpose: different surface, different treatment.
 *
 * `anthropic`, `deepseek`, `alibaba` and `moonshot` are exported from the Gate
 * Connect Figma file, because the frames draw them and those are the pixels
 * design signed off. Every other mark is vendored from lobehub/lobe-icons
 * (https://github.com/lobehub/lobe-icons, MIT) - the same set the designer
 * built the frames from, which is why the drawn layers carry its asset names
 * (`deepseek-color 1`, `moonshot 1`). The marks remain their owners'
 * trademarks, used here to identify the models they name.
 *
 * Each mark keeps **its own viewBox** rather than being rescaled to a common
 * one: the Figma exports are 16 and lobe-icons is 24, and rewriting
 * coordinates by hand is the step most likely to introduce a silent shape
 * error. `<svg>` carries `fill="currentColor"` as the default for the
 * monochrome marks; the colour ones override it per path.
 *
 * Marks with gradients or masks take their ids from `useId`, the same guard
 * `GateAiLogoMark` documents - the picker renders the whole catalogue, so one
 * mark can appear seventy times on a page and duplicate ids would be both
 * invalid and fragile.
 *
 * Deliberately absent: `aion-labs` and `nousresearch` publish detailed
 * illustrations rather than icons (73KB and 20KB), so they take the cube like
 * any other unmapped vendor. Together they are 8 of the catalogue's 413 rows.
 */

/** A mark's geometry. `g` namespaces any internal id to this instance. */
type Mark = { viewBox: string; draw: (g: (k: string) => string) => JSX.Element };

