export function ProviderMark({ name, size = 16 }: { name: ProviderName; size?: number }) {
  const uid = useId();
  const mark = MARKS[name];
  return (
    <svg
      aria-hidden
      width={size}
      height={size}
      viewBox={mark.viewBox}
      fill="currentColor"
      xmlns="http://www.w3.org/2000/svg"
    >
      {mark.draw((k) => `${uid}-${k}`)}
    </svg>
  );
}

/**
 * Which mark a model's vendor namespace carries.
 *
 * Keyed on `GateModel.vendor`, which is the catalogue's `owned_by` or, absent
 * that, the id's own namespace (`lib/toolModels.ts`). Those namespaces are not
 * clean - staging answers `x-ai` and `xai`, `z-ai` and `zai`, `moonshot` and
 * `moonshotai`, `bytedance` and `bytedance-seed` for the same companies - so
 * this table aliases rather than assuming one spelling.
 *
 * `qwen` takes the **Alibaba** mark, not lobe-icons' separate `qwen-color`,
 * because 665:18457 draws `alibaba-color 1` beside `gate/qwen3-6-35b-a3b` and
 * the file wins. It is also the largest namespace in the catalogue, so it is
 * the most visible mark in the picker.
 */
const PROVIDER_BY_VENDOR: Record<string, ProviderName> = {
  anthropic: "anthropic",
  openai: "openai",
  qwen: "alibaba",
  alibaba: "alibaba",
  google: "google",
  mistralai: "mistral",
  mistral: "mistral",
  "meta-llama": "meta",
  meta: "meta",
  deepseek: "deepseek",
  "z-ai": "zhipu",
  zai: "zhipu",
  zhipu: "zhipu",
  minimax: "minimax",
  amazon: "aws",
  aws: "aws",
  moonshotai: "moonshot",
  moonshot: "moonshot",
  nvidia: "nvidia",
  tencent: "tencent",
  "x-ai": "grok",
  xai: "grok",
  "bytedance-seed": "bytedance",
  bytedance: "bytedance",
  perplexity: "perplexity",
  cohere: "cohere",
  "ibm-granite": "ibm",
  ibm: "ibm",
  inception: "inception",
  kwaipilot: "kwaipilot",
  microsoft: "microsoft",
  morph: "morph",
  poolside: "poolside",
  relace: "relace",
  stepfun: "stepfun",
  upstage: "upstage",
  ai21: "ai21",
  baidu: "baidu",
  "arcee-ai": "arcee",
  arcee: "arcee",
  "inference-net": "inference",
  xiaomi: "xiaomimimo",
};

/**
 * The mark for a vendor namespace, or `undefined` for one with none.
 *
 * Undefined rather than a placeholder, so each call site keeps its own
 * fallback - every one of them draws `Icon name="cube"`, which is the
 * `Icon / Boxes` the frames put in the same slot.
 */
export function providerMarkFor(vendor: string, size?: number): JSX.Element | undefined {
  const name = PROVIDER_BY_VENDOR[vendor.toLowerCase()];
  return name ? <ProviderMark name={name} size={size} /> : undefined;
}
